def parse_pairs(lines):
    result = {}
    for line in lines:
        # Skip blank lines
        if line.strip() == '':
            continue

        # Check if '=' is present
        if '=' not in line:
            raise ValueError("Missing '=' in line")

        # Split on first '=' only
        parts = line.split('=', 1)
        key = parts[0].strip()
        value = parts[1].strip()

        # Reject empty key
        if key == '':
            raise ValueError("Empty key")

        # Let later duplicate keys win
        result[key] = value

    return result

