def trim_history(messages, budget):
    # Validate budget is nonnegative
    if budget < 0:
        raise ValueError("budget must be nonnegative")

    # Validate all message costs are nonnegative
    for msg in messages:
        if msg['cost'] < 0:
            raise ValueError("message cost must be nonnegative")

    # Calculate total cost of all messages
    total_cost = sum(msg['cost'] for msg in messages)

    # If total cost fits within budget, return all messages (as a new list)
    if total_cost <= budget:
        return list(messages)

    # Find the starting index of the longest contiguous suffix
    # that fits within the budget
    i = 0
    while total_cost > budget:
        total_cost -= messages[i]['cost']
        i += 1

    # Return the suffix from index i (as a new list)
    return list(messages[i:])

