def summarize_usage(events):
    max_counts = {}
    for event in events:
        request_id = event['request_id']
        input_count = event.get('input', 0)
        output_count = event.get('output', 0)
        if input_count < 0 or output_count < 0:
            raise ValueError("Negative token count not allowed")
        if request_id not in max_counts:
            max_counts[request_id] = [0, 0]
        if input_count > max_counts[request_id][0]:
            max_counts[request_id][0] = input_count
        if output_count > max_counts[request_id][1]:
            max_counts[request_id][1] = output_count
    total_input = 0
    total_output = 0
    for request_id in max_counts:
        total_input += max_counts[request_id][0]
        total_output += max_counts[request_id][1]
    return {'input': total_input, 'output': total_output}

