def trim_history(messages, budget):
    # Validate budget is nonnegative
    if budget < 0:
        raise ValueError("budget must be nonnegative")

    # Validate all message costs are nonnegative
    for message in messages:
        if message["cost"] < 0:
            raise ValueError("cost must be nonnegative")

    # Find the longest contiguous suffix whose sum fits the budget
    total = 0
    i = len(messages) - 1

    while i >= 0:
        total += messages[i]["cost"]
        if total > budget:
            break
        i -= 1

    # Return the suffix from i+1 to the end (slice does not mutate)
    return messages[i+1:]

