def merge_tool_results(calls, results):
    # Check for duplicate call ids
    seen_ids = []
    for call in calls:
        id_val = call['id']
        if id_val in seen_ids:
            raise ValueError("Duplicate call id")
        seen_ids.append(id_val)

    # Build a mapping from id to the last result (last one wins)
    result_map = {}
    for result in results:
        id_val = result['id']
        # Only store if we've seen this id in calls (ignore unknown ids)
        if id_val in seen_ids:
            result_map[id_val] = result

    # Build the result list in call order
    output = []
    for call in calls:
        id_val = call['id']
        if id_val in result_map:
            result = result_map[id_val]
            content = result.get('content', '')
            output.append({'id': id_val, 'status': 'done', 'content': content})
        else:
            output.append({'id': id_val, 'status': 'pending'})

    return output

