def merge_sorted(a, b):
    result = []
    i = 0
    j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    # Append remaining elements from a
    while i < len(a):
        result.append(a[i])
        i += 1
    # Append remaining elements from b
    while j < len(b):
        result.append(b[j])
        j += 1
    return result

